-- AmaniCare initial schema (PostgreSQL).
-- IDs are text (UUIDs or short codes generated by the app). Epoch-millisecond expiry times are BIGINT.
-- JSON payloads stay in TEXT columns so the API returns exactly what the app stored.

CREATE TABLE clinics (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  commune        TEXT NOT NULL DEFAULT '',
  city           TEXT NOT NULL DEFAULT 'Kinshasa',
  whatsapp_phone TEXT NOT NULL DEFAULT '',
  payout_method  TEXT NOT NULL DEFAULT 'bank',
  payout_account TEXT NOT NULL DEFAULT '',
  trust          INTEGER NOT NULL DEFAULT 70,
  active         INTEGER NOT NULL DEFAULT 1,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id         TEXT PRIMARY KEY,
  phone      TEXT UNIQUE NOT NULL,
  name       TEXT NOT NULL DEFAULT '',
  role       TEXT NOT NULL CHECK (role IN ('payer','family','clinic','admin')),
  lang       TEXT NOT NULL DEFAULT 'fr',
  clinic_id  TEXT REFERENCES clinics(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE otps (
  phone        TEXT PRIMARY KEY,
  code_hash    TEXT NOT NULL,
  expires_at   BIGINT NOT NULL,
  attempts     INTEGER NOT NULL DEFAULT 0,
  sent_count   INTEGER NOT NULL DEFAULT 1,
  window_start BIGINT NOT NULL
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id),
  expires_at BIGINT NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);

CREATE TABLE links (
  payer_id   TEXT NOT NULL REFERENCES users(id),
  family_id  TEXT NOT NULL REFERENCES users(id),
  relation   TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (payer_id, family_id)
);
CREATE INDEX links_family ON links(family_id);

CREATE TABLE invites (
  code       TEXT PRIMARY KEY,
  payer_id   TEXT NOT NULL REFERENCES users(id),
  relation   TEXT NOT NULL DEFAULT '',
  expires_at BIGINT NOT NULL,
  used_by    TEXT REFERENCES users(id)
);

CREATE TABLE reference_prices (
  id       TEXT PRIMARY KEY,
  name     TEXT NOT NULL,
  keywords TEXT NOT NULL,          -- JSON array of lowercase keywords (fr/en)
  usd      DOUBLE PRECISION NOT NULL
);

CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL              -- JSON
);

CREATE TABLE bill_drafts (
  id         TEXT PRIMARY KEY,
  family_id  TEXT NOT NULL REFERENCES users(id),
  photo_path TEXT NOT NULL,
  ai         TEXT,                 -- JSON snapshot of what the AI read (null if AI unavailable)
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE bills (
  id           TEXT PRIMARY KEY,
  ref          TEXT UNIQUE NOT NULL,
  family_id    TEXT NOT NULL REFERENCES users(id),
  payer_id     TEXT NOT NULL REFERENCES users(id),
  clinic_id    TEXT NOT NULL REFERENCES clinics(id),
  patient_name TEXT NOT NULL,
  bill_number  TEXT NOT NULL DEFAULT '',
  bill_date    TEXT NOT NULL DEFAULT '',
  currency     TEXT NOT NULL CHECK (currency IN ('USD','CDF')),
  items        TEXT NOT NULL,      -- JSON [{d,q,p}]
  total        DOUBLE PRECISION NOT NULL,
  total_usd    DOUBLE PRECISION NOT NULL,
  fee_usd      DOUBLE PRECISION NOT NULL DEFAULT 0,
  expected_usd DOUBLE PRECISION NOT NULL DEFAULT 0,
  ai           TEXT,
  edited       INTEGER NOT NULL DEFAULT 0,
  risk_score   INTEGER NOT NULL DEFAULT 0,
  risk_level   TEXT NOT NULL DEFAULT 'low',
  risk_reasons TEXT NOT NULL DEFAULT '[]',
  status       TEXT NOT NULL,
  photo_path   TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX bills_status ON bills(status);
CREATE INDEX bills_clinic ON bills(clinic_id);
CREATE INDEX bills_payer ON bills(payer_id);
CREATE INDEX bills_family ON bills(family_id);
CREATE INDEX bills_clinic_number ON bills(clinic_id, lower(bill_number));
CREATE INDEX bills_patient_recent ON bills(lower(patient_name), created_at);
CREATE INDEX bills_photo ON bills(photo_path);

CREATE TABLE bill_events (
  id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  bill_id  TEXT NOT NULL REFERENCES bills(id),
  at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_id TEXT,
  type     TEXT NOT NULL,
  note     TEXT NOT NULL DEFAULT ''
);
CREATE INDEX bill_events_bill ON bill_events(bill_id, id);

CREATE TABLE payments (
  id              TEXT PRIMARY KEY,
  bill_id         TEXT NOT NULL REFERENCES bills(id),
  kind            TEXT NOT NULL CHECK (kind IN ('collection','payout')),
  amount_usd      DOUBLE PRECISION NOT NULL,
  partner         TEXT NOT NULL,
  partner_ref     TEXT,
  status          TEXT NOT NULL CHECK (status IN ('pending','succeeded','failed')),
  checkout_url    TEXT,
  idempotency_key TEXT UNIQUE NOT NULL,
  failure_reason  TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX payments_bill ON payments(bill_id, kind);
CREATE INDEX payments_partner_ref ON payments(partner_ref);

CREATE TABLE messages (
  id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  to_phone   TEXT NOT NULL,
  channel    TEXT NOT NULL,
  body       TEXT NOT NULL,
  payload    TEXT,
  status     TEXT NOT NULL DEFAULT 'queued',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE audit (
  id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor_id TEXT,
  action   TEXT NOT NULL,
  detail   TEXT NOT NULL DEFAULT ''
);
